<?php $observations = (array) ($project['observations'] ?? []); $filesById=[]; foreach ((array)($project['files'] ?? []) as $file) $filesById[(int)$file['id']] = (string)$file['original_name']; ?>
<section class="sw-card"><header class="sw-section-heading"><div><h2>Observaciones</h2><p>Observaciones académicas registradas en el expediente.</p></div></header><?php if (!$observations): ?><p class="sw-empty-state">No hay observaciones registradas.</p><?php else: ?><div class="sw-record-list"><?php foreach ($observations as $item): ?><article class="sw-record"><div><strong><?= e((string)($filesById[(int)($item['file_id'] ?? 0)] ?? 'Observación general')) ?></strong><span><?= e((string)($item['category'] ?? 'General')) ?><?= !empty($item['location_reference']) ? ' · ' . e((string)$item['location_reference']) : '' ?></span></div><p><?= e((string)($item['body'] ?? '')) ?></p><small><?= e((string)($item['author_name'] ?? '')) ?> · <?= e($formatDate((string)($item['created_at'] ?? ''), true)) ?> · <?= e((string)($item['status'] ?? '')) ?></small></article><?php endforeach; ?></div><?php endif; ?></section>
